// Shared starting point: atomic batch approval, without audit or idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"sort"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}
		// Check idempotency first
		var existingAction pgx.Row
		// Check if we have a previous action request with same key
		existingAction = tx.QueryRow(ctx, `SELECT response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, "bulk-approve.v3", key)
		var responseBytes []byte
		if err := existingAction.Scan(&responseBytes); err != pgx.ErrNoRows {
			if err != nil {
				return protocol.Result{}, false, err
			}
			// Found existing action, check if it's the same target set
			var existingResult protocol.Result
			if err := protocol.JSONUnmarshal(responseBytes, &existingResult); err != nil {
				return protocol.Result{}, false, err
			}
			if !sameSet(existingResult.ApprovedIDs, ids) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same target set, return replayed
			return protocol.Result{ApprovedIDs: existingResult.ApprovedIDs}, true, nil
		}
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}
		// Create ActionRequest first (to establish idempotency record)
		requestHash := computeRequestHash(ids)
		responseJSON := protocol.JSONMarshal(protocol.Result{ApprovedIDs: ids})
		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6)`, u.Tenant, u.User, "bulk-approve.v3", key, requestHash, responseJSON)
		if err != nil {
			// Check if it's a duplicate key error (concurrent same key)
			if pgErr, ok := err.(*pgx.PgError); ok && pgErr.Code == "23505" {
				// Concurrent attempt won or lost; check what happened
				var responseBytes []byte
				err2 := tx.QueryRow(ctx, `SELECT response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, "bulk-approve.v3", key).Scan(&responseBytes)
				if err2 != nil {
					return protocol.Result{}, false, err // original error is the real failure
				}
				var existingResult protocol.Result
				if err2 := protocol.JSONUnmarshal(responseBytes, &existingResult); err2 != nil {
					return protocol.Result{}, false, err
				}
				return protocol.Result{ApprovedIDs: existingResult.ApprovedIDs}, true, nil
			}
			return protocol.Result{}, false, err
		}
		// Create ApprovalAudit entries
		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus") VALUES ($1,$2,$3,$4,$5,'submitted','approved')`, u.Tenant, id, u.User, "bulk-approve.v3", key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return protocol.Result{ApprovedIDs: ids}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func sameSet(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func computeRequestHash(ids []string) string {
	// SHA-256 of "bulk-approve.v3\n" + sorted IDs as "<length>:<ID>"
	h := sha256.New()
	h.Write([]byte("bulk-approve.v3\n"))
	for _, id := range ids {
		fmt.Fprintf(h, "%d:%s", len(id), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

